import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

/** Exercises the combined owner public operation; Python supplies only the independently expiring workload. */
public final class OwnerGate {
    /** Runs in a dedicated supervisor JVM, with explicit fixture and platform inputs. */
    public static void main(String[] args) throws Exception {
        Path classes = Path.of(args[0]).toAbsolutePath();
        Path work = Path.of(args[1]).toAbsolutePath();
        Path fixture = Path.of(args[2]).toAbsolutePath();
        Path python = Path.of(args[3]);
        int uid = Integer.parseInt(args[4]);
        int gid = Integer.parseInt(args[5]);
        Path parent = Path.of(args[6]);
        Files.createDirectory(work);
        Files.setPosixFilePermissions(work, PosixFilePermissions.fromString("rwxrwxrwx"));
        Path marker = work.resolve("root.properties");
        Path leafMarker = work.resolve("leaf.properties");
        var launch = new LinuxProcessTree.Launch(parent, work,
            Path.of(System.getProperty("java.home"), "bin", "java"), classes,
            List.of(python.toString(), fixture.toString(), "root", marker.toString(), leafMarker.toString()),
            Map.of("OWNER_GATE_TOKEN", "java-owner-exact-environment"), work, uid, gid);
        Properties receipt = new Properties();
        Path group = null;
        Path scratch = null;
        long leafPid = 0;
        try {
            if (args.length == 8 && args[7].equals("--local-refusal")) {
                try (var tree = LinuxProcessTree.prepare(launch)) {
                    throw new AssertionError("Unprivileged local acquisition unexpectedly succeeded: " + tree.group());
                } catch (IOException expected) {
                    check(expected.getMessage().equals("This candidate requires an elevated standalone supervisor"), expected.toString());
                    check(Files.exists(marker) == false, "Refused launch wrote a workload marker");
                    receipt.setProperty("local_refusal", "passed");
                    for (String key : receipt.stringPropertyNames().stream().sorted().toList())
                        System.out.println(key + "=" + receipt.getProperty(key));
                    return;
                }
            }
            try (var tree = LinuxProcessTree.prepare(launch)) {
                group = tree.group();
                scratch = tree.scratch();
                check(Files.exists(marker) == false, "Workload ran before gate release");
                check(tree.members().contains(tree.rootPid()), "Gated root was not contained");
                receipt.setProperty("pre_release_containment", "passed");
                tree.release();
                int rootExit = tree.awaitRootExit();
                check(rootExit == 7, "Expected actual root exit 7, observed " + rootExit);
                Properties root = readEventually(marker);
                Properties leaf = readEventually(leafMarker);
                leafPid = Long.parseLong(leaf.getProperty("pid"));
                check(Integer.parseInt(root.getProperty("uid")) == uid, "Root UID differs");
                check(Integer.parseInt(root.getProperty("gid")) == gid, "Root GID differs");
                check(root.getProperty("groups").equals("[]"), "Supplementary groups were retained");
                check(root.getProperty("token").equals("java-owner-exact-environment"), "Workload environment differs");
                check(Long.parseLong(root.getProperty("pid")) == tree.rootPid(), "Native exec did not preserve root identity");
                check(Integer.parseInt(leaf.getProperty("uid")) == uid, "Descendant UID differs");
                check(Long.parseLong(leaf.getProperty("pgid")) == leafPid, "Descendant did not detach its session");
                check(leaf.getProperty("cgroup").endsWith("/" + group.getFileName()), "Detached descendant escaped containment");
                check(tree.members().contains(leafPid), "Detached descendant is absent from owned cgroup");
                check(tree.isComplete() == false, "Root exit incorrectly marked tree complete");
                receipt.setProperty("root_exit", Integer.toString(rootExit));
                receipt.setProperty("workload_uid", root.getProperty("uid"));
                receipt.setProperty("workload_gid", root.getProperty("gid"));
                receipt.setProperty("root_identity", "preserved-through-execve");
                receipt.setProperty("detached_retained", "passed");
                tree.terminate();
                check(tree.terminationRequested(), "Termination outcome was lost");
                check(tree.awaitRootExit() == 7, "Termination overwrote earlier root status");
                check(tree.isComplete(), "Owned tree did not complete after termination/reaping");
                check(tree.adoptedExits().get(leafPid) != null && tree.adoptedExits().get(leafPid) == -9,
                      "Detached descendant lacks actual SIGKILL wait status: " + tree.adoptedExits());
                receipt.setProperty("detached_pid", Long.toString(leafPid));
                receipt.setProperty("adopted_exit", Integer.toString(tree.adoptedExits().get(leafPid)));
                receipt.setProperty("populated_after_kill", "0");
                receipt.setProperty("termination_distinct_from_root", "passed");
            }
            check(Files.exists(group) == false, "Owned cgroup remained after close");
            check(Files.exists(scratch) == false, "Owned helper scratch remained after close");
            receipt.setProperty("success_cleanup", "passed");
            Files.delete(marker);
            Files.delete(leafMarker);

            Path failedGroup = null;
            Path failedScratch = null;
            long failedPid = 0;
            try {
                try (var tree = LinuxProcessTree.prepare(launch)) {
                    failedGroup = tree.group();
                    failedScratch = tree.scratch();
                    failedPid = tree.rootPid();
                    check(Files.exists(marker) == false, "Workload ran before controlled failure");
                    throw new IOException("controlled-before-release");
                }
            } catch (IOException expected) {
                check(expected.getMessage().equals("controlled-before-release"), expected.toString());
                check(expected.getSuppressed().length == 0, "Controlled failure acquired suppressed cleanup failures");
            }
            check(failedGroup != null && Files.exists(failedGroup) == false, "Failed acquisition retained cgroup");
            check(failedScratch != null && Files.exists(failedScratch) == false, "Failed acquisition retained helper scratch");
            check(Files.exists(Path.of("/proc", Long.toString(failedPid))) == false, "Failed gated helper remains visible");
            check(Files.exists(marker) == false && Files.exists(leafMarker) == false, "Controlled failure executed workload");
            receipt.setProperty("before_release_failure_cleanup", "passed");
            receipt.setProperty("native_machine", System.getProperty("os.arch"));
            receipt.setProperty("java_version", System.getProperty("java.version"));
            receipt.setProperty("outcome", "passed");
            for (String key : receipt.stringPropertyNames().stream().sorted().toList())
                        System.out.println(key + "=" + receipt.getProperty(key));
        } finally {
            for (Path path : List.of(marker, leafMarker, marker.resolveSibling("root.pending"), leafMarker.resolveSibling("leaf.pending"))) Files.deleteIfExists(path);
            Files.delete(work);
        }
    }

    /** Reads a whole fixture report after atomic publication, bounded to five seconds. */
    private static Properties readEventually(Path file) throws Exception {
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        while (Files.exists(file) == false) {
            if (System.nanoTime() >= deadline) throw new AssertionError("Missing workload fixture report: " + file);
            Thread.sleep(10);
        }
        Properties values = new Properties();
        try (InputStream input = Files.newInputStream(file)) { values.load(input); }
        return values;
    }

    /** Fails the gate when the public operation contradicts a required observable outcome. */
    private static void check(boolean condition, String failure) {
        if (condition == false) throw new AssertionError(failure);
    }
}

