import java.nio.file.Path;
import java.util.List;
import java.util.Map;

/** Drives the real owner operation; no native implementation is duplicated here. */
public final class OwnerGate {
    public static void main(String[] args) throws Exception {
        Path proof = Path.of(args[0]);
        var launch = new LinuxProcessTree.Launch(Path.of("/sys/fs/cgroup"), proof.getParent(),
            Path.of(System.getProperty("java.home"), "bin", "java"), proof,
            List.of("/bin/sh", "-c", "exit 7"), Map.of(), proof.getParent(), 1001, 1001);
        try (var tree = LinuxProcessTree.prepare(launch)) {
            tree.release();
            int rootExit = tree.awaitRootExit();
            if (rootExit != 7) throw new AssertionError("Expected actual root exit 7, observed " + rootExit);
        }
    }
